    def test_all_split_retains_separate_dev_and_holdout_reports(self):
        manifest, candidate = fixture()
        holdout = copy.deepcopy(manifest["tracks"][0])
        holdout.update(id="hold", split="holdout")
        manifest["tracks"].append(holdout)
        prediction = copy.deepcopy(candidate["tracks"][0])
        prediction.update(id="hold", bpm=60)
        candidate["tracks"].append(prediction)
        splits = evaluate(manifest, candidate, split="all")["by_split"]
        self.assertEqual(1, splits["dev"]["tempo"]["exact_fraction"])
        self.assertEqual(0, splits["holdout"]["tempo"]["exact_fraction"])

