    def test_cli_external_files_audio_hash_and_json_rejection(self):
        manifest, candidate = fixture()
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            audio = root / "private.audio"
            audio.write_bytes(b"same recording and encoder origin")
            digest = hashlib.sha256(audio.read_bytes()).hexdigest()
            manifest["tracks"][0].update(
                audio_sha256=digest, audio_file=audio.name
            )
            annotation = manifest["tracks"][0].pop("annotations")
            (root / "annotation.json").write_text(json.dumps(annotation))
            manifest["tracks"][0]["annotation_file"] = "annotation.json"
            candidate["tracks"][0]["audio_sha256"] = digest
            prediction = candidate["tracks"][0]
            (root / "prediction.json").write_text(json.dumps(prediction))
            candidate["tracks"] = [
                {
                    "id": "pulse",
                    "audio_sha256": digest,
                    "prediction_file": "prediction.json",
                }
            ]
            for name, value in (
                ("manifest.json", manifest),
                ("candidate.json", candidate),
            ):
                (root / name).write_text(json.dumps(value))
            self.assertEqual(
                0,
                benchmark.main(
                    [
                        "--manifest",
                        str(root / "manifest.json"),
                        "--candidate",
                        str(root / "candidate.json"),
                        "--output",
                        str(root / "report.json"),
                        "--verify-audio",
                    ]
                ),
            )
            report = json.loads((root / "report.json").read_text())
            self.assertEqual(
                1, report["candidates"][0]["summary"]["beats"]["micro_f1"]
            )
            audio.write_bytes(b"different encoding")
            with self.assertRaises(ValueError):
                benchmark.evaluate(
                    manifest,
                    [candidate],
                    manifest_base=root,
                    candidate_bases=[root],
                    verify_audio=True,
                )
            (root / "bad.json").write_text('{"version": 1, "version": 2}')
            with self.assertRaises(ValueError):
                benchmark.read_json(root / "bad.json")


